import Ajv from 'ajv';
import type {ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  validator?: ValidateFunction;
  execute: ToolExecutor;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv({allErrors: true, unknownFormats: 'ignore'});
  private readonly compiled = new WeakMap<object, ValidateFunction>();

  private compile(definition: ToolDefinition): ValidateFunction {
    const cached = this.compiled.get(definition.inputSchema);
    if (cached) return cached;
    let validator: ValidateFunction;
    try {
      validator = this.ajv.compile(definition.inputSchema);
    } catch (error) {
      const reason = error instanceof Error ? error.message : String(error);
      throw new Error(`Invalid inputSchema for tool ${definition.name}: ${reason}`, {cause: error});
    }
    this.compiled.set(definition.inputSchema, validator);
    return validator;
  }

  private describeFailures(validator: ValidateFunction): string {
    const problems = (validator.errors ?? []).map(e => {
      const path = e.dataPath ? e.dataPath.replace(/^\./, '') : '(input)';
      const params = e.params as {missingProperty?: string; type?: string};
      if (e.keyword === 'required') return `${params.missingProperty ?? 'property'} is required`;
      if (e.keyword === 'type') return `${path} must be of type ${params.type}`;
      if (e.keyword === 'enum') return `${path} must be one of the allowed values`;
      return `${path} failed constraint ${e.keyword}`;
    });
    return `Invalid input: ${problems.join('; ')}`;
  }

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const validator = typeof definition === 'function' ? undefined : this.compile(resolved);
    this.tools.set(resolved.name, {definitionSource: definition, validator, execute});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input against the tool's inputSchema; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const validator = tool.validator ?? this.compile(this.resolveDefinition(tool.definitionSource));
    if (!validator(input)) {
      const result = this.describeFailures(validator);
      log.warn('tool', 'input rejected', {name, reason: result});
      return {result};
    }
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';

describe('ToolRegistry function-valued definitions', () => {
  it('validates against the schema returned for the current call, not a stale cached one', async () => {
    let required = 'location';
    const definition = (): ToolDefinition => ({
      name: 'dynamic_tool',
      description: 'Schema changes between calls',
      inputSchema: {type: 'object', properties: {[required]: {type: 'string'}}, required: [required]},
    });
    const registry = new ToolRegistry();
    const calls: Record<string, unknown>[] = [];
    registry.register(definition, async input => {
      calls.push(input);
      return 'ok';
    });

    const first = await registry.execute('dynamic_tool', {location: 'Berlin'});
    required = 'city';
    const second = await registry.execute('dynamic_tool', {location: 'Berlin'});

    expect({calls, first: first.result, secondMentionsCity: /city/.test(second.result)}).toEqual({
      calls: [{location: 'Berlin'}],
      first: 'ok',
      secondMentionsCity: true,
    });
  });
});

describe('ToolRegistry pass-through of valid input', () => {
  it('passes valid input with an unlisted extra property to the executor unchanged, exactly once', async () => {
    const registry = new ToolRegistry();
    const calls: Record<string, unknown>[] = [];
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      async input => {
        calls.push(input);
        return 'ok';
      }
    );

    const response = await registry.execute('get_weather', {location: 'Berlin', units: 'metric'});

    expect({calls, response}).toEqual({calls: [{location: 'Berlin', units: 'metric'}], response: {result: 'ok'}});
  });
});
